def pending(events):
    """Return (key, value) pairs for keys still open, oldest opening first.

    Each event is (operation, key, value). Keys and values are strings.
    A put opens an absent key or updates an open key without changing its
    place. A drop closes an open key and is harmless for an absent key.
    A subsequent put of a closed key opens it at the end. Only put and
    drop occur. The value of a drop is ignored.
    """
    order = {}
    values = {}
    for operation, key, value in events:
        if operation == "put":
            order.setdefault(key, None)
            values[key] = value
        else:
            values.pop(key, None)
            order.pop(key, None)
    return [(key, values[key]) for key in order if key in values]

