import unittest
from pending import pending


class PendingTests(unittest.TestCase):
    def test_update_keeps_position(self):
        events = [("put", "b", "1"), ("put", "a", "2"), ("put", "b", "3")]
        self.assertEqual(pending(events), [("b", "3"), ("a", "2")])

    def test_drop(self):
        self.assertEqual(pending([("put", "a", ""), ("drop", "a", "-")]), [])
